function precinctModal(){
  const enough=S.evidence.length>=6&&['ledger','register','witness','autopsy'].every(x=>S.evidence.includes(x))&&S.interviews.silas;
  const actions=[{label:'PIN EVIDENCE TO THE BOARD',run:()=>{S.flags.boardReviewed=true;log('Evidence reviewed at the precinct','The scene mark, witness account, parish records, and medical window are compared. Clove and wool remain suggestive, not identifying.');advance(20,'analysis');openModal('The case board','MAJOR CRIMES · ANALYSIS',`<p>The Ninth Verse predates the current deaths by decades. The token links the scene to parish attendance, but not to a killer. Jonah’s account places an unknown person near the tower; the medical estimate narrows the window.</p><div class="statusline">${enough?'THE EVIDENCE SUPPORTS A NARROW, SEARCHABLE THEORY.':'MORE INDEPENDENT CORROBORATION IS NEEDED BEFORE A WARRANT.'}</div><p class="subtle">A theory is not proof. Do not treat scent, ritual staging, or rumor as identification.</p>`,[{label:'BACK TO PRECINCT',run:closeModal}])}}];

input.newString:
function boardPairResult(ids){
  const has=(...clues)=>clues.every(id=>ids.includes(id));
  if(has('sigil','ledger'))return {title:'The scene mark echoes the Ninth Verse',status:'SUPPORTED CONNECTION',text:'The broken-arc mark and parish text share imagery. This supports a link between the staging and parish material, but does not identify who made it or who caused Mara’s death.'};
  if(has('witness','autopsy'))return {title:'The witness time needs clarification',status:'TIMELINE TENSION',text:'Jonah recalls a voice around 9:13, while the medical estimate places death earlier. His hour is uncertain; revisit the statement before treating this as a contradiction or an alibi.'};
  if(has('register','letter'))return {title:'Both leads point toward the archives',status:'LEAD · NOT CORROBORATION',text:'The sign-out record and Mara’s letter independently mention archive activity, but neither establishes that Crowe and Mara met or that the records relate to the death.'};
  if(has('fiber','token'))return {title:'Two items share the scene, not a source',status:'NO SOURCE LINK',text:'The wool fiber and choir token were found at the tower. Their shared location does not show who brought either item there.'};
  return {title:'No established connection yet',status:'UNRESOLVED',text:'These items do not currently support a reliable link. Keep them separate until another independent observation provides a testable connection.'};
}
function caseBoardModal(){
  boardSelection=[];boardFeedback='';boardFeedbackKind='';
  const render=()=>{
    const clues=S.evidence.filter(id=>evidenceData[id]);
    const cards=clues.map(id=>`<button type="button" class="board-clue ${boardSelection.includes(id)?'selected':''}" data-clue="${id}" aria-pressed="${boardSelection.includes(id)}"><b>${evidenceData[id].name}</b><small>${evidenceData[id].kind}</small></button>`).join('');
    const feedback=boardFeedback?`<div class="board-feedback ${boardFeedbackKind}"><b>${boardFeedback.title}</b><span>${boardFeedback.status}</span><p>${boardFeedback.text}</p></div>`:'';
    openModal('Work the case board','MAJOR CRIMES · EVIDENCE ANALYSIS',`<p>Select two or three logged clues, then test the connection. The board distinguishes corroboration, tension, and coincidence—none is a verdict.</p><div class="board-clues">${cards||'<p>No evidence to compare yet. Collect a clue first.</p>'}</div><div class="board-selection">${boardSelection.length}/3 CLUES SELECTED</div>${feedback}`,[{label:'TEST CONNECTION',kind:'primary',run:()=>{if(boardSelection.length<2){toast('SELECT AT LEAST TWO CLUES');return}const result=boardPairResult(boardSelection);boardFeedback=result;boardFeedbackKind=result.status==='SUPPORTED CONNECTION'?'supported':result.status==='TIMELINE TENSION'?'tension':'open';S.flags.boardReviewed=true;S.theories=S.theories||[];const record={clues:[...boardSelection],title:result.title,status:result.status,text:result.text};const existing=S.theories.findIndex(t=>t.clues?.slice().sort().join('|')===record.clues.slice().sort().join('|'));if(existing>=0)S.theories[existing]=record;else S.theories.unshift(record);S.theories=S.theories.slice(0,12);log('Evidence connection tested',`${result.title}: ${result.status}. ${result.text}`);save('auto');render()}},{label:'CLOSE BOARD',run:closeModal}]);
    const root=$('modalRoot');root.querySelectorAll('[data-clue]').forEach(button=>button.onclick=()=>{const id=button.dataset.clue;if(boardSelection.includes(id))boardSelection=boardSelection.filter(x=>x!==id);else if(boardSelection.length<3)boardSelection.push(id);else toast('A MAXIMUM OF THREE CLUES CAN BE TESTED');render()});
  };
  render();
}
function precinctModal(){
  const enough=S.evidence.length>=6&&['ledger','register','witness','autopsy'].every(x=>S.evidence.includes(x))&&S.interviews.silas;
  const actions=[{label:'WORK THE CASE BOARD',kind:'primary',run:caseBoardModal}];

