   function churchModal(){const actions=[];if(!S.evidence.includes('ledger'))actions.push({label:'REQUEST ACCESS TO HYMN LEDGER',kind:'primary',run:()=>{const silasSeen=!!S.interviews.silas;S.sect++;addEvidence('ledger');S.interviews.silas=(S.interviews.silas||0)+1;advance(35,'church');log('Silas Crowe interviewed','The archivist says the Ninth Verse was a teaching metaphor, but his initials appear beside the annotation.');openModal('Silas Crowe','PARISH ARCHIVIST · RECORDED INTERVIEW',`<div class="person-details"><span class="person-avatar avatar-one">SC</span><div><h3>Silas Crowe</h3><small>PARISH ARCHIVIST · 52 · RESIDENT 19 YEARS</small></div></div><div class="dialogue-line">“It’s an old hymn, Detective. People write in margins. The ninth verse is a warning against pride, not a prophecy.”</div><p>He offers the ledger without hesitation, then asks whether police intend to search the parish. He smells faintly of clove. You cannot tell whether this is meaningful or ordinary.</p><div class="statusline">INTERVIEW ${silasSeen?'UPDATED':'RECORDED'} · NO PROBABLE CAUSE ESTABLISHED</div>`,[{label:'ASK ABOUT HIS INITIALS',run:()=>{S.interviews.silas=(S.interviews.silas||0)+1;S.killerrisk+=4;S.player.stress+=4;log('Crowe questioned about the ledger','He says he catalogued the volume years ago. He is calm, but asks who else has seen the margin.');toast('CROWE KNOWS YOU HAVE THE LEDGER');closeModal()}},{label:'END INTERVIEW',run:closeModal}])}});if(!S.evidence.includes('register'))actions.push({label:'SEARCH PUBLIC CATALOG',run:()=>{addEvidence('register');S.sect++;advance(18);openModal('The choir register','PARISH ARCHIVE · CATALOG ENTRY',`<p>A ledger sign-out card shows Silas Crowe borrowed the restricted choir register four weeks ago. The book has not been returned. The parish secretary says the older volumes are sometimes used for restoration.</p><span class="tag unverified">LEAD · OBTAIN ORIGINAL REGISTER BEFORE CONCLUSION</span>`,[{label:'RETURN TO ARCHIVE',run:closeModal}])}});actions.push({label:'EXAMINE THE NAVE',run:()=>{S.player.stress=Math.min(100,S.player.stress+8);advance(15);openModal('A silence between bells','ST. ORAN · NAVE',`<p>The last rows are damp though the roof is sound. For one breath, the stained glass seems to show a figure standing behind you. When you turn, only the empty aisle remains.</p><p class="subtle">Stress rose. The experience may be exhaustion, suggestion, or something you cannot verify.</p>`,[{label:'COLLECT YOURSELF',run:()=>{S.player.stress=Math.max(0,S.player.stress-4);closeModal()}}])}});actions.push({label:'LEAVE PARISH',run:closeModal});openModal('St. Oran Parish','PARISH HALL · FOUNDED 1891',`<p>Warm candlelight and rain-dark coats. The parish is open for evening prayer. A volunteer tells you the bell has been kept silent since the storm, then corrects herself: “Except the one time.”</p><div class="statusline">SECT LEAD · THE LANTERN OF THE NINTH DAWN</div>`,actions)}

