79:   function dinerModal(){const talked=S.interviews.jonah;openModal('The Lantern Diner','OLD HARBOR · LAST CALL',`<p>Fluorescent light pools across empty booths. A cook wipes the same clean counter over and over. He watches you in the mirror before you speak.</p><div class="dialogue-line">“I told the patrol what I remember. I don’t want to be in the paper.”</div>${talked?'<p class="subtle">Jonah recognizes you. His account is preserved; he is more nervous now that the story is circulating.</p>':''}`,[{label:talked?'ASK ABOUT THE VOICE AGAIN':'ASK WHAT HE SAW',run:()=>{S.interviews.jonah=(S.interviews.jonah||0)+1;S.public++;if(!S.evidence.includes('witness'))addEvidence('witness');S.player.stress=Math.min(100,S.player.stress+3);log('Jonah Pike interviewed','The witness recalled a calm voice asking about the tower latch. Clove and wet wool. He is uncertain of the hour.');advance(24,'interview');openModal('A witness statement','INTERVIEW · JONAH PIKE',`<p>${talked?'On the second telling Jonah changes one detail:':'Jonah rubs his thumb along the edge of a coffee mug.'} “The voice wasn’t shouting. Asked about the tower door. Like they already knew it stuck. I smelled clove, maybe. It was raining hard.”</p><p class="subtle">Reliability: partial. His timeline is consistent with the dispatch window, but he admits he was closing his eyes between orders.</p><div class="statusline">STATEMENT RECORDED · DO NOT TREAT SCENT AS IDENTIFICATION</div>`,[{label:'THANK HIM',run:closeModal},{label:'PRESS HIM ON THE TIME',run:()=>{S.player.stress+=5;S.interviews.jonah=(S.interviews.jonah||0)+1;log('Witness pressured','Jonah withdrew certainty about the time. The core account remains.');toast('JONAH WITHDRAWS TIME ESTIMATE');closeModal()}}])}},{label:'BUY COFFEE · REST',run:()=>{S.player.fatigue=Math.max(0,S.player.fatigue-15);S.player.stress=Math.max(0,S.player.stress-5);advance(20);toast('COFFEE · A MOMENT OF QUIET');closeModal()}},{label:'LEAVE',run:closeModal}])}
